PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users  (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE orders (id INTEGER PRIMARY KEY AUTOINCREMENT, claim_hash TEXT UNIQUE NOT NULL, claimed_by INTEGER, claimed_at INTEGER, note TEXT, created_at INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'new', kind TEXT NOT NULL DEFAULT 'standard', customer_name TEXT, customer_email TEXT, ship_to TEXT, color_hex TEXT, amount_cents INTEGER, stripe_session TEXT, tracking TEXT, shipped_at INTEGER, claim_code TEXT);
CREATE TABLE signs  (id TEXT PRIMARY KEY, order_id INTEGER, owner_id INTEGER, label TEXT, destination TEXT, updated_at INTEGER, archived_at INTEGER, reserved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE scans  (id INTEGER PRIMARY KEY AUTOINCREMENT, sign_id TEXT NOT NULL, ts INTEGER NOT NULL, country TEXT);
CREATE TABLE login_tokens (token_hash TEXT PRIMARY KEY, email TEXT NOT NULL, claim_hash TEXT, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL, expires_at INTEGER NOT NULL);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_scans_sign ON scans (sign_id, ts);
CREATE UNIQUE INDEX idx_orders_stripe ON orders (stripe_session) WHERE stripe_session IS NOT NULL;
